const research = $input.first().json;
const ctx = $('Prepare Research Fetch Input').first().json._ctx;
return [{ json: { channel_id: ctx.channel_id, prompt_name: 'publication-metadata-generation', _ctx: Object.assign({}, ctx, { research_summary: research || null }) } }];

const prompt = $json.data;
const ctx = $('Prepare Get-Prompt Input').first().json._ctx;
const model = (prompt.model_compatibility && prompt.model_compatibility[0]) || 'claude-opus-4-8';
const userPayload = {
  topic: ctx.topic, script_content: ctx.script_content, research_summary: ctx.research_summary,
  final_video: { duration_seconds: ctx.final_video && ctx.final_video.duration_seconds },
  channel: { style: ctx.style, publication_policy: ctx.publication_policy, target_audience: ctx.channel && ctx.channel.target_audience }
};
const schema = {"title":"Publication Metadata Response","description":"Structured output of the publication-metadata-generation LLM call, before persist_metadata_variants(). Chapter start times and the deterministic attribution block are computed server-side, never trusted from this response — chapter_labels here supplies TEXT ONLY (see docs/architecture/publication-package-pipeline.md#chapters). `titles` must contain at least 5 genuinely different options.","type":"object","additionalProperties":false,"required":["titles","description_summary","chapter_labels","tags","hashtags","pinned_comment","community_post","promotional_copy"],"properties":{"titles":{"type":"array","minItems":5,"items":{"title":"Title Variant","description":"One title option from the publication-metadata-generation LLM call — see docs/architecture/publication-package-pipeline.md#title-rules. `approach` documents which strategy this title takes (direct/explanatory, curiosity-driven, outcome-focused, contrarian, data-specific) so reviewers can see the titles are genuinely varied, not five near-identical rewordings.","type":"object","additionalProperties":false,"required":["text"],"properties":{"text":{"type":"string","minLength":1,"maxLength":100},"approach":{"type":["string","null"]}}}},"description_summary":{"type":"string","minLength":1},"value_proposition":{"type":["string","null"]},"context":{"type":["string","null"]},"cta_text":{"type":["string","null"]},"intro_chapter_label":{"type":["string","null"],"description":"Label for the always-present 0:00 introduction chapter (covering the hook+intro narration). Defaults to \"Introduction\" if omitted."},"chapter_labels":{"type":"array","description":"One entry per script section_id. Text only — start times are always computed server-side from the voiceover's own timing package, never from this field.","items":{"type":"object","additionalProperties":false,"required":["section_id","label"],"properties":{"section_id":{"type":"string","minLength":1},"label":{"type":"string","minLength":1}}}},"tags":{"type":"array","items":{"type":"string","minLength":1}},"hashtags":{"type":"array","items":{"type":"string","pattern":"^#"}},"pinned_comment":{"type":"string"},"community_post":{"type":"string"},"promotional_copy":{"type":"string"},"disclaimers_text":{"type":["string","null"],"description":"Deterministically assembled from the channel's publication_policy.disclaimers by the caller before this is persisted — never authored by the LLM."}}};
return [{ json: {
  ctx, model,
  requestBody: { model, max_tokens: 8192, system: prompt.content, messages: [{ role: 'user', content: JSON.stringify(userPayload) }], output_config: { format: { type: 'json_schema', schema } } }
} }];

const resp = $input.first().json;
const ctx = $('Prepare Anthropic Request').first().json.ctx;
const model = $('Prepare Anthropic Request').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null; let parse_failed = true;
if (textBlock) { try { result = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, metadata: result, usage: resp.usage || {}, provider_request_id: resp.id || null, _raw_text: textBlock ? textBlock.text : null, repaired: false } }];

const p = $('Parse Response').first().json;
const orig = $('Prepare Anthropic Request').first().json.requestBody;
const repairMessages = orig.messages.concat([{ role: 'assistant', content: p._raw_text || '' }, { role: 'user', content: 'Your previous response was not valid JSON matching the required schema. Return ONLY the corrected JSON object matching the schema -- no prose, no markdown fences.' }]);
return [{ json: { ctx: p.ctx, model: p.model, requestBody: { ...orig, messages: repairMessages } } }];

const resp = $input.first().json;
const ctx = $('Prepare Repair Request').first().json.ctx;
const model = $('Prepare Repair Request').first().json.model;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null; let parse_failed = true;
if (textBlock) { try { result = JSON.parse(textBlock.text); parse_failed = false; } catch (e) { parse_failed = true; } }
return [{ json: { parse_failed, ctx, model, metadata: result, usage: resp.usage || {}, provider_request_id: resp.id || null, repaired: true } }];

const j = $('Parsed Result').first().json; const ctx = j.ctx;
const inputTokens = j.usage.input_tokens || 0; const outputTokens = j.usage.output_tokens || 0;
const cost = Math.round(((inputTokens / 1000000) * 5 + (outputTokens / 1000000) * 25) * 1000000) / 1000000;
return [{ json: { channel_id: ctx.channel_id, content_project_id: ctx.content_project_id, workflow_run_id: ctx.workflow_run_id, workflow_step_id: null, provider: 'anthropic', service_type: 'llm', model: j.model, quantity: inputTokens + outputTokens, unit: 'token', unit_price_usd: null, total_cost_usd: cost, provider_request_id: j.provider_request_id, estimated: false, metadata: { repaired: !!j.repaired }, _cost: cost } }];

const j = $('Parsed Result').first().json; const ctx = j.ctx; const parsed = j.metadata;
const disclaimers = (ctx.publication_policy && ctx.publication_policy.disclaimers) || [];
const disclaimersText = Array.isArray(disclaimers) && disclaimers.length > 0 ? disclaimers.join('\n') : null;
const shared = {
  description_summary: parsed.description_summary, value_proposition: parsed.value_proposition || null, context: parsed.context || null,
  cta_text: parsed.cta_text || null, intro_chapter_label: parsed.intro_chapter_label || null, chapter_labels: parsed.chapter_labels || [],
  tags: parsed.tags || [], hashtags: parsed.hashtags || [], pinned_comment: parsed.pinned_comment || '', community_post: parsed.community_post || '',
  promotional_copy: parsed.promotional_copy || '', disclaimers_text: disclaimersText,
};
return [{ json: { ctx, titles: parsed.titles, shared, model: j.model, provider_request_id: j.provider_request_id } }];

const persisted = $('Persist Metadata Variants').first().json;
const ctx = $('Parsed Result').first().json.ctx;
const model = $('Parsed Result').first().json.model || 'claude-opus-4-8';
const variants = persisted.data.variants;
const systemPrompt = "You are fact-checking YouTube video titles against the video's approved script for unsupported factual claims. For each title, return grounding_status 'valid' if every specific fact/number/date/name/claim in the title is supported by the provided script, or 'invalid' if the title asserts something not present in the material. Be conservative -- only mark 'invalid' for a genuine unsupported factual claim, not stylistic language. Return only the structured array matching the schema.";
const userPayload = { script_content: ctx.script_content, titles: variants.map((v) => ({ metadata_variant_id: v.metadata_variant_id, title: v.title })) };
const schema = { type: 'array', items: { type: 'object', additionalProperties: false, required: ['metadata_variant_id', 'grounding_status'], properties: { metadata_variant_id: { type: 'string', format: 'uuid' }, grounding_status: { type: 'string', enum: ['valid', 'invalid'] }, notes: { type: ['string', 'null'] } } } };
return [{ json: { ctx, variants, requestBody: { model, max_tokens: 4096, system: systemPrompt, messages: [{ role: 'user', content: JSON.stringify(userPayload) }], output_config: { format: { type: 'json_schema', schema } } } } }];

const resp = $input.first().json;
const { ctx, variants } = $('Prepare Grounding Review Input').first().json;
const textBlock = (resp.content || []).find((b) => b.type === 'text');
let result = null;
if (textBlock) { try { result = JSON.parse(textBlock.text); } catch (e) { result = null; } }
if (!Array.isArray(result)) {
  result = variants.map((v) => ({ metadata_variant_id: v.metadata_variant_id, grounding_status: 'valid', notes: 'grounding review response was unparseable; defaulted to valid' }));
}
const byId = {}; for (const r of result) byId[r.metadata_variant_id] = r;
const complete = variants.map((v) => byId[v.metadata_variant_id] || { metadata_variant_id: v.metadata_variant_id, grounding_status: 'valid', notes: 'no verdict returned; defaulted to valid' });
return [{ json: { ctx, groundings: complete } }];

const persisted = $('Persist Metadata Variants').first().json;
const groundings = $('Parse Grounding Response').first().json.groundings;
return [{ json: { success: true, data: Object.assign({}, persisted.data, { groundings }), error: null, runtime: persisted.runtime } }];
